Denote $x_{\xi}=\sum_{i=1}^n\xi_ix_i(0)$,
$x(t)=(x_1(t),\cdots,x_n(t))^T$, and $H(x(t))=(h(x_1(t)),
\cdots,h(x_n(t)))^T$. Then equations (\ref{P1a}) can be rewritten in
the compact form as
\begin{eqnarray}
\dot{x}(t)=-LH(x(t))\label{com}
\end{eqnarray}

Define a function as:
\begin{eqnarray}
V(x(t))=\sum\limits_{i=1}^n\xi_i\int_{0}^{x_i(t)}h(s)ds
\end{eqnarray}
Obviously, $V(x(t))\geq 0$ is radially unbounded, and $V(x(t))=0$
if and only if $x(t)=0$.

Denote $B=(b_{ij})=(\Xi L+L^T\Xi)/2$, where
$\Xi=\mathrm{diag}(\xi)$. It is easy to check that $B$ is a
symmetric matrix with zero row-sum, i.e., $B$ can be regarded as a
graph Laplacian of a bi-graph. Differentiating $V(x(t))$ and using
Lemma \ref{dec}, we have
\begin{eqnarray}
\dot{V}(x(t))&=&-\sum\limits_{i=1}^n\xi_ih(x_i(t))\sum\limits_{j\in
\mathcal{N}_i}{l}_{ij}h(x_j(t))\nonumber\\
&=&-H(x(t))^T{\Xi L}H(x(t))=-H(x(t))^TBH(x(t))\nonumber\\
&=&\sum\limits_{i>j}b_{ij}(h(x_i(t))-h(x_j(t)))^2\leq 0,~~~~
(\mathrm{since}~~b_{ij}\le 0) \label{dev}
\end{eqnarray}
Thus, $0\le V(x(t))\leq V(x(0))$, which implies $x(t)$ is bounded
for any $t\geq 0$. And the largest invariant subset ($\Omega$-limit
set) for the equations (\ref{P1a}) is
\begin{eqnarray}
\Omega=\{x:x_i(t)=x_j(t); i,j=1,\cdots,n\}\label{invariance}
\end{eqnarray}

Now, we claim that for all $i=1,\cdots,n$,
$\lim\limits_{t\rightarrow\infty}x_{i}(t)=x_{\xi}$.

In fact, if $t_{m}\rightarrow\infty$ and for all $i,j=1,\cdots,n$,
$x_{i}(t_{m})\rightarrow\beta$, then,
\begin{eqnarray}
x_{\xi}=
\lim\limits_{t\rightarrow\infty}\sum\limits_{i=1}^{n}\xi_ix_i(t_{m})
=\sum\limits_{i=1}^{n}\xi_i\beta=\beta
\end{eqnarray}
which means that $x_{\xi}$ is the group decision of the consensus
problem. Theorem 1 is proved completely.

\begin{myrem}
Let $h(x_i(t))=\alpha x_i(t)$ with $\alpha>0$, The nonlinear
function $h(\cdot)$ becomes a linear function. therefore, Theorem 1
can be regarded as a generalization of the consensus problem under
linear protocols. It also give a simple proof for the consensus
problem under linear protocols, too.
\end{myrem}

\begin{myrem}
Assume $(h(w_1)-h(w_2))/(w_1-w_2)\geq \alpha$ holds for $\alpha>0$
and any $w_1\not=w_2\in R$. In this case, we have
\begin{eqnarray}
\dot{V}(x(t))=\sum\limits_{i>j}b_{ij}(h(x_i(t))-h(x_j(t)))^2
\leq\alpha^2\sum\limits_{i>j}b_{ij}(x_i(t)-x_j(t))^2
\end{eqnarray}
and the consensus problem will be realized exponentially. Moreover,
it seems that the nonlinear protocol can be realized faster than
that under the linear protocol $h(w)=\alpha w$. Therefore, nonlinear
protocols can be applied to calculate the average value of
large-scale networks more effectively.
\end{myrem}

\quad In this simulation, we choose two protocols.
One is the nonlinear protocol
\begin{eqnarray}
h^{\star}(x_i)=\left\{\begin{array}{ccl}
x_i^2           & ;&\mathrm{if}\quad x_i>1\\
\sqrt{x_i}      & ;&\mathrm{if}\quad 0<x_i\leq 1\\
-\sqrt{-x_i}    & ;&\mathrm{if}\quad -1<x_i\leq 0\\
-x_i^2          & ;&\mathrm{if}\quad x_i\leq-1
\end{array}\right.\label{non}
\end{eqnarray}
The other is the linear protocol
\begin{eqnarray}
h(x_i)=x_i/2\qquad i=1,2,3 \label{lin}
\end{eqnarray}
